}

public class Solution {
    public ListNode swapPairs(ListNode A) {
        ListNode dummy = new ListNode(0);
        dummy.next = A;
        ListNode prev = dummy;
        while (prev.next != null && prev.next.next != null) {
            ListNode first = prev.next;
            ListNode second = first.next;
            first.next = second.next;
            second.next = first;
            prev.next = second;
            prev = first;
        }
        return dummy.next;
    }
}

public class Solution {
    public ListNode addTwoNumbers(ListNode A, ListNode B) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        int carry = 0;
        while (A != null || B != null || carry != 0) {
            int sum = carry;
            if (A != null) { sum += A.val; A = A.next; }
            if (B != null) { sum += B.val; B = B.next; }
            carry = sum / 10;
            tail.next = new ListNode(sum % 10);
            tail = tail.next;
        }
        return dummy.next;
    }
}

public class Solution {
    public int solve(ListNode A) {
        java.util.List<Integer> v = new java.util.ArrayList<>();
        for (ListNode c = A; c != null; c = c.next) v.add(c.val);
        int n = v.size(), best = 0;
        for (int c = 0; c < n; c++) {
            best = Math.max(best, expand(v, c, c));       // odd-length centre
            best = Math.max(best, expand(v, c, c + 1));   // even-length centre
        }
        return best;
    }
    private int expand(java.util.List<Integer> v, int l, int r) {
        int len = 0;
        while (l >= 0 && r < v.size() && v.get(l).equals(v.get(r))) {
            len += (l == r) ? 1 : 2;
            l--; r++;
        }
        return len;
    }
}

public class Solution {
    public ListNode getIntersectionNode(ListNode A, ListNode B) {
        if (A == null || B == null) return null;
        ListNode p = A, q = B;
        while (p != q) {
            p = (p == null) ? B : p.next;
            q = (q == null) ? A : q.next;
        }
        return p;
    }
}

public class Solution {
    private int capacity;
    private HashMap<Integer, ListNode> map;
    private DoublyLinkedList cache;

    public Solution(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.cache = new DoublyLinkedList();
    }

    public int get(int key) {
        if (map.containsKey(key)) {
            int data = cache.removeFromCache(map.get(key));
            ListNode newNode = cache.insertAtLast(key, data);
            map.put(key, newNode);
            return data;
        }
        return -1;
    }

    public void set(int key, int value) {
        ListNode current;
        if (!map.containsKey(key)) {
            if (map.size() == capacity) {
                int keyRemoved = cache.removeAtStart();
                map.remove(keyRemoved);
            }
        } else {
            cache.removeFromCache(map.get(key));
        }
        current = cache.insertAtLast(key, value);
        map.put(key, current);
    }
}

class DoublyLinkedList {
    ListNode head;
    ListNode tail;

    DoublyLinkedList() {
        this.head = new ListNode(-1, -1);
        this.tail = new ListNode(-1, -1);
        head.next = tail;
        tail.prev = head;
    }

    public ListNode insertAtLast(int key, int val) {
        ListNode newNode = new ListNode(key, val);
        tail.prev.next = newNode;
        newNode.prev = tail.prev;
        newNode.next = tail;
        tail.prev = newNode;
        return newNode;
    }

    public int removeAtStart() {
        // returns the key of the least-recently-used node removed
        ListNode lru = head.next;
        removeFromCache(lru);
        return lru.key;
    }

    public int removeFromCache(ListNode node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
        return node.val;
    }
}

/**
 * Definition for singly-linked list.
 * class ListNode {
 *     public int val;
 *     public ListNode next;
 *     ListNode(int x) { val = x; next = null; }
 * }
 */
public class Solution {
    public ListNode solve(ListNode A) {
        return detectStartNodeOfTheLoopAndBreak(A);
    }

    public ListNode detectStartNodeOfTheLoopAndBreak(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        ListNode slow = head;
        ListNode fast = head.next;

        // Step 1: Detect loop
        while (fast != null && fast.next != null) {
            if (slow == fast) {
                break;
            }
            slow = slow.next;
            fast = fast.next.next;
        }

        // Step 2: If no loop, return head
        if (fast == null || fast.next == null || slow != fast) {
            return head;
        }

        // Step 3: Find the start of the loop
        slow = head;
        fast = fast.next;   // fast was one step ahead initially, realign

        while (slow != fast) {
            slow = slow.next;
            fast = fast.next;
        }

        // slow == loop-start. Walk the cycle to the node whose next is the
        // loop-start and cut it. (Handles the loop-starts-at-head case, where
        // the old prev-based cut threw a NullPointerException.)
        ListNode p = slow;
        while (p.next != slow) {
            p = p.next;
        }
        p.next = null;

        return head;
    }
}

/**
 * Definition for singly-linked list.
 * class ListNode {
 *     public int val;
 *     public ListNode next;
 *     ListNode(int x) { val = x; next = null; }
 * }
 */
public class Solution {
    public ListNode reorderList(ListNode A) {
        if (A == null || A.next == null) {
            return A;
        }

        // Step 1: find the middle
        ListNode slow = A, fast = A;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // Step 2: reverse the second half
        ListNode second = slow.next;
        slow.next = null;
        ListNode prev = null;
        while (second != null) {
            ListNode nxt = second.next;
            second.next = prev;
            prev = second;
            second = nxt;
        }
        second = prev;

        // Step 3: merge the two halves
        ListNode first = A;
        while (second != null) {
            ListNode f1 = first.next;
            ListNode s1 = second.next;
            first.next = second;
            second.next = f1;
            first = f1;
            second = s1;
        }

        return A;
    }
}

/**
 * Definition for singly-linked list.
 * class ListNode {
 *     public int val;
 *     public ListNode next;
 *     ListNode(int x) { val = x; next = null; }
 * }
 */
public class Solution {
    public ListNode partition(ListNode A, int B) {
        ListNode lessDummy = new ListNode(0);
        ListNode geDummy = new ListNode(0);
        ListNode less = lessDummy, ge = geDummy;

        ListNode cur = A;
        while (cur != null) {
            if (cur.val < B) {
                less.next = cur;
                less = less.next;
            } else {
                ge.next = cur;
                ge = ge.next;
            }
            cur = cur.next;
        }

        ge.next = null;
        less.next = geDummy.next;
        return lessDummy.next;
    }
}

